    "section": "口頭作文",
    "front": "日本の自然",
    "back": "В Япо́нии краси́вая приро́да.\n\nЕсть го́ры, моря́, леса́ и ре́ки.\nМне о́чень нра́вится приро́да Хокка́йдо.",
